  const session=body.sessionContext,changed=new Set((session?.changedSkills||[]).map((skill:any)=>skill.id)),selected=(body.selectedSkills||[]),skillsForPrompt=session?.mode==='continuation'?selected.filter((skill:any)=>changed.has(skill.id)):selected;
