  const wholeImageRule=guided&&(guided.purpose==='views'||guided.purpose==='depth')?(locale==='ru'?'Не создавайте балансные изображения и не разделяйте голову с волосами или тело с одеждой на этом этапе.':'Do not create balance images or split the head from its hair or the body from its clothing in this stage.'):'';
  const hairGuidance=localizedHairGuidance(guided,locale)+localizedRestingHairGuidance(guided,locale),headTemplates=localizedHeadViewTemplates(guided,locale),textureReferenceGuidance=localizedTextureReferenceGuidance(guided,body.stage,locale)+localizedGroupSemanticGuidance(guided,body.stage,locale);
  const depthHairRule=(guided?.purpose==='depth'||guided?.purpose==='correction'&&guided.correctionTarget?.targetPurpose==='depth')&&guided?.headHairMode?(locale==='ru'?'\nДля карты глубины сохраните точный парный текущий цветной ракурс и его причёску/силуэт. На этапе 2.5 он ещё может ожидать проверки: сохраните его хэш и reviewStatus и не помечайте принятым. Не упрощайте и не перерисовывайте волосы; стройте глубину по этой точной цветной форме.':'\nFor this depth map, preserve the exact paired current color view and its hairstyle/silhouette. The view may still be pending review during step 2.5; preserve its recorded hash and reviewStatus and never mark it accepted. Do not simplify or redraw hair; derive depth from that exact color shape.'):'';
  const correction=guided?.correctionTarget;
  const conditioningRule=localizedConditioningGuidance(guided,locale);
  const guidedInstruction=!guided?'':guided.purpose==='views'?(locale==='ru'?'Создайте только выбранные целые виды головы со всеми волосами или тела в одежде. Сохраните идентичность, пропорции, асимметрию и материал.':'Create only the selected views of the complete head with all hair or the clothed body. Preserve identity, proportions, asymmetry, and materials.'):guided.purpose==='depth'?(locale==='ru'?'Для каждого выбранного текущего цветного ракурса, в том числе ожидающего проверки на этапе 2.5, создайте согласованную карту глубины: ровный чёрный фон, ближние поверхности светлее, дальние темнее, читаемый объём и единая ориентация. Сохраните точный парный хэш и reviewStatus; не помечайте ожидающий ракурс принятым. Не применяйте фильтр глубины.':'For each selected current color view, including one still pending human review in step 2.5, make a coherent depth map with a uniform black background, near surfaces lighter and far surfaces darker, readable volume, and consistent orientation. Keep the exact paired hash and reviewStatus; never mark a pending color view accepted. Do not apply a depth filter.'):guided.purpose==='texture-references'?(locale==='ru'?'Используйте фактическую группу, её передний и задний гайды сетки, принятый цветовой референс и исходник. Сохраните одинаковый масштаб и прозрачный фон; следуйте проекционному силуэту группы без требования UV.':'Use the actual component group, its front and back mesh guides, accepted color references, and source artwork. Keep equal scale and a transparent background; follow the projected group silhouette without requiring UVs.'):guided.purpose==='correction'?(locale==='ru'?(`Исправьте ровно целевой слот ${correction?.targetSlotId||'из манифеста'}, кандидат ${correction?.targetCandidateId||'текущий'}, артефакт ${correction?.targetArtifactId||'указан в манифесте'}, SHA-256 ${correction?.targetHash||'указан в манифесте'} (${correction?.part||''} ${correction?.view||''} ${correction?.group||''}). Режим: ${correction?.editMode==='fresh-reference'?'новый референс':'редактирование текущего'}. Исходный цвет/материал закреплён как референс. Сохраните отмеченные protectedSlots и preserve; прежние байты остаются в истории, результат — новая версия с явным принятием человеком. Для текстур используйте нейтральный свет без запечённых теней; маркировки сохраняйте краской/эмиссией, не геометрией; карты глубины имеют чёрный фон и ясно читаемый силуэт ключевых форм, рта и хвоста. Замечание пользователя: ${correction?.userNote||guided.note||''}`):(`Correct exactly target slot ${correction?.targetSlotId||'in manifest'}, candidate ${correction?.targetCandidateId||'current'}, artifact ${correction?.targetArtifactId||'in manifest'}, SHA-256 ${correction?.targetHash||'in manifest'} (${correction?.part||''} ${correction?.view||''} ${correction?.group||''}). Mode: ${correction?.editMode==='fresh-reference'?'fresh reference':'edit current'}. Pin the source color/material reference. Preserve protectedSlots and preserve; retain prior bytes and submit a new version for explicit human acceptance. For textures use neutral lighting without baked shadows; keep markings as paint/emission rather than added geometry; depth maps use a black background and clear key silhouette, mouth, and tail volume. User note: ${correction?.userNote||guided.note||''}`)):'';
