  const stylePath=styleSkill?.closure?.['references/depth-style-example.png']?path.resolve(work,path.dirname(styleSkill.path),'references/depth-style-example.png'):null;
  const depthStyleRule=!depthRequest?'':locale==='ru'?`\nОбязательно откройте и передайте генератору два изображения: 1 — точный парный цветной ракурс (геометрия и персонаж); 2 — ${stylePath||'references/depth-style-example.png из активного навыка глубины'} (только способ изображения объёма). Лист с четырьмя видами — образец стиля, не источник персонажа. Результат — один отдельный ракурс, не коллаж. Не требуйте калиброванный Z-buffer или точное равенство RGB в каждом пикселе; используйте мягкие объёмные переходы как в образце. Проверка допускает малые отклонения нейтрального RGB без изменения файла. Не обрабатывайте результат генератора фильтрами. После отправки проверьте submission.selected и точный artifactId: запись только в историю не означает замену текущего слота.`:`\nOpen and attach two images to the generator: 1 — the exact paired color view (character and geometry); 2 — ${stylePath||'references/depth-style-example.png in the active depth skill'} (volume representation only). The four-view sheet is a style example, not a character source. Deliver one standalone view, never a collage. Do not demand a calibrated Z-buffer or exact RGB equality at every pixel; use the example's soft volumetric transitions. The neutral-RGB check tolerates minor encoding differences without changing bytes. Never filter the generator output. After submission verify submission.selected and the exact artifactId: a history-only record does not replace the current slot.`;
  const retryRule=localizedRetryGuidance(guided,locale);
